INSERT INTO aikido_group_detail_cache (group_id, issue_type, title, description, severity, severity_score,  package_name, current_version, fixed_version, cve_id, cve_description,  cvss_score, repo_name, repo_url, container_image, how_to_fix,  related_cve_ids, group_status, time_to_fix_minutes, fetched_at, updated_at) VALUES (8666111,'surface_monitoring','CSP config allows inline javascript','Content Security Policy (CSP) is a first line of defense against common attacks including Cross Site Scripting (XSS) and data injection attacks. In this case your CSP header is set, but it''s configured to still allow for inline javascript. Inline JS is one of the most common techniques used in XSS. Blocking inline javascript blocks an entire class of attacks. Adding this defense has a high return on investment.','high',85,'unknown','','','',NULL,NULL,'ms-switchbox',NULL,NULL,'Ensure that your web server, application server, load balancer, etc. is properly configured to set the Content-Security-Policy header.','[]'::jsonb,'todo',1080,'2026-04-04 21:40:47.378537+02','2026-04-04 21:40:47.378537+02') ON CONFLICT (group_id) DO UPDATE SET issue_type=EXCLUDED.issue_type, title=EXCLUDED.title, description=EXCLUDED.description, severity=EXCLUDED.severity, severity_score=EXCLUDED.severity_score, package_name=EXCLUDED.package_name, current_version=EXCLUDED.current_version, fixed_version=EXCLUDED.fixed_version, cve_id=EXCLUDED.cve_id, cve_description=EXCLUDED.cve_description, cvss_score=EXCLUDED.cvss_score, repo_name=EXCLUDED.repo_name, repo_url=EXCLUDED.repo_url, container_image=EXCLUDED.container_image, how_to_fix=EXCLUDED.how_to_fix, related_cve_ids=EXCLUDED.related_cve_ids, group_status=EXCLUDED.group_status, time_to_fix_minutes=EXCLUDED.time_to_fix_minutes, updated_at=now();
INSERT INTO aikido_group_detail_cache (group_id, issue_type, title, description, severity, severity_score,  package_name, current_version, fixed_version, cve_id, cve_description,  cvss_score, repo_name, repo_url, container_image, how_to_fix,  related_cve_ids, group_status, time_to_fix_minutes, fetched_at, updated_at) VALUES (8666113,'surface_monitoring','CSP policy does not block the use of eval()','Content Security Policy (CSP) is a first line of defense against common attacks including Cross Site Scripting (XSS) and data injection attacks. In this case your CSP config is set, but it does not block the use of eval(), setTimeout() and other functions that can run unknown code. The use of eval is sometimes a technique that can enable code injection in the front-end, leading to XSS attacks which may lead to account takeovers and API abuse. blocking eval() blocks an entire class of attacks, so adding this has a high return on investment.','high',75,'unknown','','','',NULL,NULL,'ms-switchbox',NULL,NULL,'Ensure that your web server, application server, load balancer, etc. is properly configured to set the Content-Security-Policy header.','[]'::jsonb,'todo',360,'2026-04-04 21:44:29.768989+02','2026-04-04 21:44:29.768989+02') ON CONFLICT (group_id) DO UPDATE SET issue_type=EXCLUDED.issue_type, title=EXCLUDED.title, description=EXCLUDED.description, severity=EXCLUDED.severity, severity_score=EXCLUDED.severity_score, package_name=EXCLUDED.package_name, current_version=EXCLUDED.current_version, fixed_version=EXCLUDED.fixed_version, cve_id=EXCLUDED.cve_id, cve_description=EXCLUDED.cve_description, cvss_score=EXCLUDED.cvss_score, repo_name=EXCLUDED.repo_name, repo_url=EXCLUDED.repo_url, container_image=EXCLUDED.container_image, how_to_fix=EXCLUDED.how_to_fix, related_cve_ids=EXCLUDED.related_cve_ids, group_status=EXCLUDED.group_status, time_to_fix_minutes=EXCLUDED.time_to_fix_minutes, updated_at=now();
